import test from 'node:test';
import assert from 'node:assert/strict';
import {limitedDigest} from './limited-research-preview.mjs';
import {parseLimitedReleaseControl,verifyLimitedControlEvidence,verifyLimitedRuns,LIMITED_JOB,LIMITED_WORKFLOW} from './limited-research-approval.mjs';
import contract from '../../contracts/financial_correction_v1.json' with {type:'json'};
const now=Date.parse('2026-10-16T15:00:00Z'),h='a'.repeat(64),s='b'.repeat(40),scope='limited-research-preview-v1';
function fixture() {
 const assessment={schema_version:'limited-research-assessment-v1',scope_id:scope,publication_authority:'none',ui_sha:s,blocking_failures:[],accepted_performance_limitations:['1440: P1 exact limits not met (3500ms / 400ms / 200ms)'],original_design_failures:['1440: P1 exact limits not met (3500ms / 400ms / 200ms)'],financial_cases:['NVDA','FUTU','AAOI','ALH','AVT'].flatMap(symbol=>[[1440,'dark'],[390,'light']].map(([width,theme])=>({symbol,viewport:{width},theme,source:{original_category:{status:'unavailable',reason:'Original authentic source is expired; actual mandatory state remains unknown'}}})))};
 assessment.performance_measurements=[{label:'current',viewport:{width:1440},runs:Array.from({length:3},()=>({candidate_ms:3000,method_switch_ms:450,longest_initial_task_ms:100})),candidate_median_ms:3000,maximum_switch_ms:450,longest_initial_task_ms:100}];assessment.radar_measurements=[];
 const screenshots=Object.fromEntries(['NVDA','FUTU','AAOI','ALH','AVT'].flatMap(symbol=>[[1440,'dark'],[390,'light']].flatMap(([width,theme])=>['evidence','annual-viewport',...(['FUTU','ALH'].includes(symbol)?['history']:[]),...(symbol==='NVDA'?['selection','purchase']:[])].map(view=>[`financial-${symbol}-${view}/${width}/${theme}`,h]))));
 assessment.screens=Object.entries(screenshots).map(([key,sha256])=>({key,sha256}));
 const noticeBytes='Limited research preview. Expired mandatory evidence remains unknown.';
 const assessmentBytes=JSON.stringify(assessment),review={schema_version:'limited-research-review-v1',scope_id:scope,ui_sha:s,assessment_sha256:limitedDigest(assessmentBytes),reviewer:'synthetic fixture only',screens:Object.keys(screenshots).map(key=>({key,screenshot_sha256:h,scores:Object.fromEntries(['design','usability','originality','content'].map(k=>[k,{value:8,reason:'synthetic test reason'}]))}))};
 const evidence={assessmentBytes,reviewBytes:JSON.stringify(review),screenshotsBytes:JSON.stringify(screenshots),noticeBytes};
 const approval={schema_version:'limited-research-approval-v1',scope_id:scope,status:'draft',created_at:'2026-10-16T14:00:00Z',expires_at:'2026-10-16T16:00:00Z',controller_sha:s,ui:{sha:s,inventory_sha256:h},predecessor:{identity:'synthetic-predecessor',receipt_sha256:h},data:{manifest_sha256:h,logical_inventory_sha256:h,financial_lineage_sha256:h},evidence:{ci:{id:1,attempt:1},assessment_run:{id:2,attempt:1},assessment_sha256:limitedDigest(evidence.assessmentBytes),review_sha256:limitedDigest(evidence.reviewBytes),screenshots_sha256:limitedDigest(evidence.screenshotsBytes),notice_sha256:limitedDigest(noticeBytes)},accepted_performance_failures:assessment.accepted_performance_limitations,owner_acceptance:null};
 const context={controller_sha:s,ui:approval.ui,predecessor:approval.predecessor,data:approval.data,correction_hold:false,renewal_hold:false,source_admission_pending:false};
 return {approval,evidence,context,assessment,review};
}

function controlFixture(){const f=fixture();f.approval.status='approved';f.approval.owner_acceptance={reference:'SYNTHETIC OWNER ACCEPTANCE FOR TEST ONLY',accepted_at:'2026-10-16T14:30:00Z'};return {schema_version:'limited-research-release-control-v1',approval:f.approval,capture:{run_id:2,run_attempt:1,job_id:200,artifact_id:300,artifact_name:'limited-research-preview-2-1',artifact_sha256:h,capture_sha256:h},financial:{},assessment:f.evidence.assessmentBytes,review:f.evidence.reviewBytes,screenshots:f.evidence.screenshotsBytes,notice:f.evidence.noticeBytes};}
function apiFixture(c){const repository='kusennjp1-ai/screener',responses={};for(const [id,path,event,names] of [[1,'.github/workflows/ci.yml','push',contract.required_ci_jobs],[2,LIMITED_WORKFLOW,'workflow_dispatch',[LIMITED_JOB]]]){responses[`repos/${repository}/actions/runs/${id}/attempts/1`]={id,run_attempt:1,repository:{full_name:repository},head_repository:{full_name:repository},head_branch:'main',head_sha:s,path,event,status:'completed',conclusion:'success'};responses[`repos/${repository}/actions/runs/${id}/attempts/1/jobs?per_page=100`]=[{jobs:names.map((name,i)=>({name,id:id===2?200:10+i,run_id:id,head_sha:s,run_attempt:1,status:'completed',conclusion:'success',started_at:'2026-10-16T14:00:00Z',completed_at:'2026-10-16T14:20:00Z'}))}];}responses[`repos/${repository}/actions/artifacts/300`]={id:300,name:c.capture.artifact_name,digest:'sha256:'+h,expired:false,workflow_run:{id:2,head_sha:s,head_branch:'main'},size_in_bytes:100,created_at:'2026-10-16T14:10:00Z',expires_at:'2026-10-17T14:10:00Z'};return {repository,responses,api:path=>{assert.ok(Object.hasOwn(responses,path),path);return responses[path];}};}
test('finite release control activates only within accepted window while historical audit survives expiration',()=>{const c=controlFixture();parseLimitedReleaseControl(JSON.stringify(c),{activation:true,now});assert.throws(()=>parseLimitedReleaseControl(JSON.stringify(c),{activation:true,now:now+86400000}),/window/);parseLimitedReleaseControl(JSON.stringify(c),{now:now+86400000});c.approval.status='draft';c.approval.owner_acceptance=null;assert.throws(()=>parseLimitedReleaseControl(JSON.stringify(c)),/window|accepted/);});
test('raw immutable assessment, review and screenshot bytes remain exact',()=>{const c=controlFixture();verifyLimitedControlEvidence(c,c.assessment);for(const key of ['assessment','review','screenshots','notice']){const changed=structuredClone(c);changed[key]+=' ';assert.throws(()=>verifyLimitedControlEvidence(changed,changed.assessment),/Changed/);}});
test('closed release control rejects extras and malformed exact artifact pin',()=>{for(const edit of [c=>c.enabled=true,c=>c.capture.expired=false,c=>c.capture.run_attempt=2,c=>c.capture.artifact_name='other']){const c=controlFixture();edit(c);assert.throws(()=>parseLimitedReleaseControl(JSON.stringify(c),{activation:true,now}));}});
test('exact complete main CI and separate assessment jobs authenticate immutable attempts',()=>{const c=controlFixture(),f=apiFixture(c),v=verifyLimitedRuns(c,f.repository,f.api,{artifact:true,now});assert.equal(v.checks.length,contract.required_ci_jobs.length+1);assert.equal(v.artifact.id,300);});
test('wrong SHA, branch, event, workflow, conclusion, repository or attempt fails closed',()=>{for(const edit of [r=>r.head_sha='c'.repeat(40),r=>r.head_branch='other',r=>r.event='pull_request',r=>r.path='.github/workflows/design-acceptance.yml',r=>r.conclusion='failure',r=>r.repository.full_name='other/repo',r=>r.run_attempt=2]){const c=controlFixture(),f=apiFixture(c);edit(f.responses[`repos/${f.repository}/actions/runs/2/attempts/1`]);assert.throws(()=>verifyLimitedRuns(c,f.repository,f.api,{artifact:true,now}),/attempt/);}});
test('missing duplicate failed or wrong exact job rejects',()=>{for(const edit of [j=>j.pop(),j=>j.push(structuredClone(j[0])),j=>j[0].conclusion='failure',j=>j[0].id=201,j=>j[0].run_id=999,j=>j[0].head_sha='c'.repeat(40),j=>j[0].started_at='invalid',j=>j[0].completed_at='invalid']){const c=controlFixture(),f=apiFixture(c);edit(f.responses[`repos/${f.repository}/actions/runs/2/attempts/1/jobs?per_page=100`][0].jobs);assert.throws(()=>verifyLimitedRuns(c,f.repository,f.api,{artifact:true,now}),/job/);}});
test('artifact expiration digest origin size and creation boundaries fail closed',()=>{for(const edit of [a=>a.expired=true,a=>a.expires_at='2026-10-16T14:59:59Z',a=>a.digest='sha256:'+'b'.repeat(64),a=>a.workflow_run.id=3,a=>a.size_in_bytes=2147483649,a=>a.created_at='2026-10-16T13:00:00Z']){const c=controlFixture(),f=apiFixture(c);edit(f.responses[`repos/${f.repository}/actions/artifacts/300`]);assert.throws(()=>verifyLimitedRuns(c,f.repository,f.api,{artifact:true,now}),/artifact/);}});
